
using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;
public static class ManagedModuleTool {
 static IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> roots){foreach(var t in roots){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
 public static void Main(string[] args){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(Path.GetDirectoryName(args[1]));foreach(var version in new[]{"6.0.36","8.0.31","9.0.16"})resolver.AddSearchDirectory(@"C:\Program Files\dotnet\shared\Microsoft.NETCore.App\"+version);using(var module=ModuleDefinition.ReadModule(args[1],new ReaderParameters{ReadingMode=ReadingMode.Deferred,AssemblyResolver=resolver})){if(args[0]=="network"){foreach(var r in module.GetMemberReferences())if(r.DeclaringType.FullName.StartsWith("System.Net")||r.DeclaringType.FullName.StartsWith("System.Diagnostics.Process")||r.Name.StartsWith("LoadFrom"))Console.WriteLine(r.FullName);return;}if(args[0]=="references"){foreach(var r in module.AssemblyReferences)Console.WriteLine(r.Name+" "+r.Version);return;}int from=args.Length>3?int.Parse(args[3]):0,to=args.Length>4?int.Parse(args[4]):0,ports=0,strings=0,guards=0;var urls=new HashSet<string>();foreach(var t in Types(module.Types))foreach(var m in t.Methods.Where(m=>m.HasBody)){if(args[0]=="patch"&&m.ReturnType.FullName=="System.Boolean"&&new[]{"IsCrowdControlClientAvailable","IsCrowdControlProcessRunning","IsCrowdControlSemaphorePresent"}.Contains(m.Name)){m.Body.ExceptionHandlers.Clear();m.Body.Instructions.Clear();m.Body.Instructions.Add(Instruction.Create(OpCodes.Ldc_I4_1));m.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));guards++;}foreach(var ins in m.Body.Instructions){if(ins.OpCode==OpCodes.Ldc_I4&&ins.Operand is int&&(int)ins.Operand==from&&from>0){if(args[0]=="patch")ins.Operand=to;ports++;}if(ins.OpCode!=OpCodes.Ldstr)continue;string s=(string)ins.Operand;if(s.StartsWith("http://")||s.StartsWith("https://")||s.StartsWith("wss://")){try{urls.Add(new Uri(s).Host);}catch{}}if(args[0]=="audit"&&(s.Contains("127.0.0.1")||s.Contains("localhost")))Console.WriteLine("LOCAL\t"+t.FullName+"::"+m.Name+"\t"+s.Replace("\n"," "));if(args[0]=="patch"&&!s.Contains(".dll")&&!s.Contains(".exe")&&!s.Contains(".ini")&&!s.Contains(".json")&&!s.Contains("BepInEx/")&&!s.Contains("BepInEx\\")){string n=s.Replace("Crowd Control","ShenPulse").Replace("[CrowdControl]","[ShenPulse]");if(n!=s){ins.Operand=n;strings++;}}}}
 if(args[0]=="patch"){foreach(var t in Types(module.Types))foreach(var a in t.CustomAttributes)if(a.AttributeType.Name=="BepInPlugin"&&a.ConstructorArguments.Count>=2){var old=a.ConstructorArguments[1];if(old.Value is string)a.ConstructorArguments[1]=new CustomAttributeArgument(old.Type,((string)old.Value).Replace("Crowd Control","ShenPulse").Replace("CrowdControl","ShenPulse"));}if(from>0&&ports==0)throw new InvalidOperationException("Port attendu absent");module.Write(args[2]);}Console.WriteLine("COUNTS\t"+ports+"\t"+strings+"\t"+guards);foreach(var u in urls.OrderBy(x=>x))Console.WriteLine("HOST\t"+u);}}
}
